INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('66dbeb18-a9e3-404d-bf44-9cb4ddf9e60e', 'note', 'A Vision of AI', '{"body": "# A Vision of AI\n\nHumans have imagined intelligent machines for millennia — from myth to mechanical hoax to modern AGI rhetoric.\n\n- **Yan Shi** built a robot for King Mu of Zhou (Chinese mythology)\n- **Talos** — the bronze guardian of Crete (Greek mythology)\n- **Schachtürke** (1779) — Kempelen''s chess-playing \"automaton\" (actually a hidden human)\n- **Frankenstein''s monster** (Mary Shelley, 1816) — the literary blueprint for \"creature out of control\"\n- **Sam Altman** talks frequently about Artificial General Intelligence (AGI)\n- **Ray Kurzweil** and other tech-optimists describe a future \"Singularity\""}', NULL, NULL, '{"color": "#a855f7", "design": "swirl"}', '2026-05-26 07:56:37.361893+00', '2026-05-26 07:56:37.361893+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('c73f4a8e-5ea4-4c8e-822d-dcd8b4e266c2', 'note', 'Turing Test (1950)', '{"body": "Alan Turing''s \"Imitation Game\" from his 1950 paper.\n\nIf a person can no longer distinguish a machine''s answers from those of a human, the machine has passed the test and is of \"human-like intelligence.\""}', '66dbeb18-a9e3-404d-bf44-9cb4ddf9e60e', NULL, '{}', '2026-05-26 07:56:37.376119+00', '2026-05-26 07:56:37.376119+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('174eec40-fe86-4dbd-9aa9-00c54190a6aa', 'note', 'Mythology of Automata', '{"body": "- Yan Shi (China) — robot for King Mu of Zhou\n- Talos (Greece) — bronze guardian of Crete\n\nThe idea of building artificial life is much older than computing."}', '66dbeb18-a9e3-404d-bf44-9cb4ddf9e60e', NULL, '{}', '2026-05-26 07:56:37.376119+00', '2026-05-26 07:56:37.376119+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('ee6a3788-33be-41a7-a775-1a60e5533eb1', 'note', 'Schachtürke (1779)', '{"body": "Wolfgang von Kempelen''s \"Mechanical Turk\" — a chess-playing automaton that toured Europe. Eventually revealed as a hoax: a human chess master was hidden inside the cabinet.\n\nLesson: when something looks like AI, ask what''s actually happening underneath."}', '66dbeb18-a9e3-404d-bf44-9cb4ddf9e60e', NULL, '{}', '2026-05-26 07:56:37.376119+00', '2026-05-26 07:56:37.376119+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('adbbebcc-fbf2-48e6-b4ba-ecfd34193c59', 'note', 'Frankenstein (1816)', '{"body": "Mary Shelley''s novel — the archetypal story of a created intelligence its creator can no longer control.\n\nStill the dominant cultural frame for AI risk discussion."}', '66dbeb18-a9e3-404d-bf44-9cb4ddf9e60e', NULL, '{}', '2026-05-26 07:56:37.376119+00', '2026-05-26 07:56:37.376119+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('4b838d4f-7e21-49cd-a08b-79f655b0604a', 'note', 'AGI & Singularity', '{"body": "**AGI (Artificial General Intelligence):** a system with broad, human-level cognitive capability. Heavily promoted by Sam Altman (OpenAI).\n\n**Singularity:** Ray Kurzweil''s thesis that AI progress will reach a point of recursive self-improvement after which prediction breaks down."}', '66dbeb18-a9e3-404d-bf44-9cb4ddf9e60e', NULL, '{}', '2026-05-26 07:56:37.376119+00', '2026-05-26 07:56:37.376119+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('109390d9-369d-4ced-a65b-11be405dafe5', 'file', 'Lecture slides (PDF)', '{"url": "/uploads/e601469dbddb87a8bbef65db.pdf", "mime": "application/pdf", "size": 10685634, "filename": "Generative AI_Englisch.pdf"}', '66dbeb18-a9e3-404d-bf44-9cb4ddf9e60e', NULL, '{}', '2026-05-26 07:56:37.376119+00', '2026-05-26 07:56:37.376119+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('2a3c3afd-6c38-4a94-8f4e-2c91df7eb2b9', 'note', 'AI Milestones', '{"body": "# AI Milestones\n\nA tour of \"is this AI, or just software?\" moments. Rodney Brooks: *\"Every time we figure out a piece of it, it stops being magical; we say, ''Oh, that''s just a computation''.\"*"}', NULL, NULL, '{"color": "#06b6d4", "design": "craters"}', '2026-05-26 07:56:37.382656+00', '2026-05-26 07:56:37.382656+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('c60f161e-db71-40ab-8d43-8fa463e42487', 'note', 'Spell Checkers (1970s–80s)', '{"body": "Programs that could detect spelling errors were considered AI.\n\nWhy it seemed intelligent: the computer appeared to \"understand\" language and find mistakes."}', '2a3c3afd-6c38-4a94-8f4e-2c91df7eb2b9', NULL, '{}', '2026-05-26 07:56:37.387076+00', '2026-05-26 07:56:37.387076+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('9fe509ff-8a5c-4c18-be6e-013413dfa68a', 'note', 'Deep Blue beats Kasparov (1997)', '{"body": "IBM''s Deep Blue defeated world champion Garry Kasparov.\n\nConsidered a major AI milestone — machines beating humans at complex strategy. Critics argued it used \"brute force methods\" rather than true intelligence.\n\nToday: chess programs are common training tools for chess players."}', '2a3c3afd-6c38-4a94-8f4e-2c91df7eb2b9', NULL, '{}', '2026-05-26 07:56:37.387076+00', '2026-05-26 07:56:37.387076+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('0b9fcfee-91f2-40c6-bda4-4daf2d7163b9', 'note', 'MYCIN (1976)', '{"body": "Stanford developed MYCIN to diagnose blood infections.\n\n- Used **450+ rules** from medical experts\n- Pattern: IF patient has fever AND bacteria type is X, THEN prescribe antibiotic Y\n- Matched the accuracy of human specialists in controlled tests\n\nOnce understood as \"organised checklists programmed by humans,\" it became *knowledge engineering* — not AI."}', '2a3c3afd-6c38-4a94-8f4e-2c91df7eb2b9', NULL, '{}', '2026-05-26 07:56:37.387076+00', '2026-05-26 07:56:37.387076+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('d97705b0-02c8-48f9-9814-baaee81e574d', 'note', 'Netflix Recommendations', '{"body": "AI, or \"just software\"?\n\n- Based on trend analysis, Netflix produced *House of Cards* (2013)\n- Uses machine learning, analyses millions of users, improves over time\n- \"Just statistics\": finding correlations like *people who watched X also watched Y*\n\nThe system doesn''t truly \"understand\" preferences — it finds patterns in data."}', '2a3c3afd-6c38-4a94-8f4e-2c91df7eb2b9', NULL, '{}', '2026-05-26 07:56:37.387076+00', '2026-05-26 07:56:37.387076+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('530032ca-929b-4f7c-80f9-02ab70ae034e', 'note', 'AlphaGo (2016)', '{"body": "Google DeepMind''s AlphaGo defeated Go world champion Lee Sedol in South Korea.\n\nGo is enormously complex — one estimation puts the number of possible games at ~10^600."}', '2a3c3afd-6c38-4a94-8f4e-2c91df7eb2b9', NULL, '{}', '2026-05-26 07:56:37.387076+00', '2026-05-26 07:56:37.387076+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('5c804bff-9e83-4c1a-b794-efa321c15096', 'note', 'Voice Assistants', '{"body": "**Siri, Alexa, ChatGPT** — AI or not?\n\n- Natural language processing, voice recognition, adapt to your speech patterns\n- Most responses come from databases or simple web searches\n- Siri and Alexa today can''t handle complex conversations like ChatGPT — mainly pattern matching and lookup tables"}', '2a3c3afd-6c38-4a94-8f4e-2c91df7eb2b9', NULL, '{}', '2026-05-26 07:56:37.387076+00', '2026-05-26 07:56:37.387076+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('646f725b-57ce-4824-8f6c-19fb78b24965', 'note', 'AI Numbers & Market', '{"body": "# AI Numbers & Market\n\nThe scale of generative AI adoption in 2024–2025."}', NULL, NULL, '{"color": "#eab308", "design": "bands"}', '2026-05-26 07:56:37.392546+00', '2026-05-26 07:56:37.392546+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('d80a5789-8d90-4deb-a275-320ca1f31f3f', 'note', 'Headline numbers', '{"body": "- **100M users** — ChatGPT reached in just 2 months. Fastest-growing consumer tool ever (Reuters)\n- **$244B → $826B** — Projected global AI market 2025→2030 (Statista)\n- **$33.9B** — Global investment in generative AI in 2024, +18.7% YoY (Stanford AI Index)\n- **75%** — Knowledge workers worldwide using generative AI on the job in 2024\n- **$644B** — Projected global spending on generative AI in 2025, +76% from 2024 (Gartner)\n- **280×** — How much the cost of AI model inference at GPT-3.5-level fell from Nov 2022 to Oct 2024"}', '646f725b-57ce-4824-8f6c-19fb78b24965', NULL, '{}', '2026-05-26 07:56:37.397071+00', '2026-05-26 07:56:37.397071+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('687c0220-80a5-4c23-a22e-14a3b0c19b2f', 'note', 'GDPval (OpenAI, 2025)', '{"body": "**GDPval:** Evaluating AI model performance on real-world, economically valuable tasks.\n\nOpenAI 2025 benchmark — moves the conversation from synthetic benchmarks to tasks that map onto labour-market value."}', '646f725b-57ce-4824-8f6c-19fb78b24965', NULL, '{}', '2026-05-26 07:56:37.397071+00', '2026-05-26 07:56:37.397071+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('4b11689d-df76-4bda-a807-71fb80d7fe16', 'note', 'AI Adoption in Companies', '{"body": "# AI Adoption in Companies\n\nWhat the data actually shows about enterprise AI returns.\n\n*MIT Project NANDA, July 2025 — \"The State of AI in Business 2025\"*\n\nBased on: 300 initiatives, 52 user/manager interviews, 152 senior-executive responses."}', NULL, NULL, '{"color": "#f97316", "design": "bands"}', '2026-05-26 07:56:37.400816+00', '2026-05-26 07:56:37.400816+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('6042289c-9891-423d-87c1-c232080d00b0', 'note', 'The 95% finding', '{"body": "- **95%** of initiatives do not generate a return on investment within six months of start\n- **~70%** of investments go into marketing and sales (easier to measure)\n- **>90%** adoption of personal AI tools, but returns are more indirectly measurable\n- **67%** of initiatives involving service providers are piloted (vs 33% internally), on average every second one"}', '4b11689d-df76-4bda-a807-71fb80d7fe16', NULL, '{}', '2026-05-26 07:56:37.404349+00', '2026-05-26 07:56:37.404349+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('ee232455-24c5-484a-9d4b-eacffeab46ff', 'note', 'Dynamic System Prompts', '{"body": "The static instructions for an LLM can be **programmed** so they reflect different situations: time of day, information about the user, current task.\n\nTurns one \"assistant\" into many context-specific assistants."}', '28e3ccd1-cd00-4202-a5e1-b6649da8b943', NULL, '{}', '2026-05-26 07:56:37.474824+00', '2026-05-26 07:56:37.474824+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('c82542b0-acf5-4a7e-8e7b-c3dcf8be6f07', 'note', 'Where AI gets used', '{"body": "**Sales & Marketing:** outbound emails, lead scoring, personalised campaign content, follow-up automation, competitive analysis, social media sentiment monitoring.\n\n**Organization:** internal workflow orchestration, document consolidation, resource allocation, process monitoring.\n\n**Customer Service:** call consolidation and routing, chatbots, ticket routing.\n\n**Finance & Procurement:** contract classification and tagging, supplier risk alerts, accounts payable and receivable."}', '4b11689d-df76-4bda-a807-71fb80d7fe16', NULL, '{}', '2026-05-26 07:56:37.404349+00', '2026-05-26 07:56:37.404349+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('1a96cad5-851a-46ee-9452-6f6cfc645a3e', 'note', 'Inside LLMs', '{"body": "# Inside LLMs\n\nHow large language models actually work under the hood — from probability to tokens to billions of parameters."}', NULL, NULL, '{"color": "#3b82f6", "design": "rings"}', '2026-05-26 07:56:37.409175+00', '2026-05-26 07:56:37.409175+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('bf2d7497-6050-4276-b516-cc2a86750fc4', 'note', 'Statistical Language Models', '{"body": "Based on a given text, you can calculate the probability of each word in that text.\n\nBetter: based on that, you can calculate the probability of the **next** word given the current word.\n\nThat''s the foundation everything else is built on."}', '1a96cad5-851a-46ee-9452-6f6cfc645a3e', NULL, '{}', '2026-05-26 07:56:37.413324+00', '2026-05-26 07:56:37.413324+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('03d43f4e-7583-4f70-a06b-9b8c6ff6b3c7', 'note', 'Tokens, not words', '{"body": "A machine does not read words — it turns words into numbers.\n\nExample: `\"Hello, my name is Christian\"` → `[13225, 11, 922, 1308, 382, 12607]`\n\nA token is a chunk of a word, a whole word, or punctuation. The model only ever sees integers."}', '1a96cad5-851a-46ee-9452-6f6cfc645a3e', NULL, '{}', '2026-05-26 07:56:37.413324+00', '2026-05-26 07:56:37.413324+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('8da6a7fd-d5a9-4e14-ac35-3fca02567767', 'note', 'From small to big models', '{"body": "**GPT-3 (2020):** 175 billion parameters, ~$4.6 million in compute costs.\n\nMore parameters → more capacity to capture nuance, but also higher cost and latency."}', '1a96cad5-851a-46ee-9452-6f6cfc645a3e', NULL, '{}', '2026-05-26 07:56:37.413324+00', '2026-05-26 07:56:37.413324+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('73dad272-ec31-4837-b438-17e26af2cbcd', 'note', 'Attention Mechanism', '{"body": "Natural language has a context problem: to generate the next word, you need to know the whole sentence.\n\nSince 2017, **Transformer Models** (the \"T\" in GPT) use the **Attention Mechanism** to weight which earlier tokens matter for the next prediction.\n\nThe model learns the context of each token — how it relates to other tokens in the dataset.\n\n*Vaswani et al., \"Attention is All You Need\" (2017).*"}', '1a96cad5-851a-46ee-9452-6f6cfc645a3e', NULL, '{}', '2026-05-26 07:56:37.413324+00', '2026-05-26 07:56:37.413324+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('98d16675-b0a6-405e-9b5c-4f0d09f0cf75', 'iframe', 'Token visualizer', '{"url": "https://tokenvisualizer.netlify.app"}', '1a96cad5-851a-46ee-9452-6f6cfc645a3e', NULL, '{}', '2026-05-26 07:56:37.413324+00', '2026-05-26 07:56:37.413324+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('e9ba95ab-dba9-47b3-ab04-0838217851b2', 'iframe', 'Transformer Explainer', '{"url": "https://poloclub.github.io/transformer-explainer"}', '1a96cad5-851a-46ee-9452-6f6cfc645a3e', NULL, '{}', '2026-05-26 07:56:37.413324+00', '2026-05-26 07:56:37.413324+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('14b93948-8fa6-40d5-93c6-22fa780c72d2', 'note', 'Machine Learning', '{"body": "# Machine Learning\n\nThree learning paradigms that go into a modern LLM."}', NULL, NULL, '{"color": "#10b981", "design": "craters"}', '2026-05-26 07:56:37.417166+00', '2026-05-26 07:56:37.417166+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('27ff8557-faa1-43b3-88a5-8da5b7067064', 'note', 'Unsupervised Learning', '{"body": "Large language models are given vast amounts of text within which they search for patterns.\n\nWhen patterns are found, they are weighted with probabilities, and connections between tokens are established.\n\nNo labels — the model discovers structure on its own."}', '14b93948-8fa6-40d5-93c6-22fa780c72d2', NULL, '{}', '2026-05-26 07:56:37.421312+00', '2026-05-26 07:56:37.421312+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('366c38bf-a870-43ca-befb-7babc0fb91ce', 'note', 'Supervised Learning', '{"body": "Question-and-answer pairs are prepared for the model to learn and prioritise.\n\nHumans curate the \"right\" answer, and the model is nudged toward that style of response."}', '14b93948-8fa6-40d5-93c6-22fa780c72d2', NULL, '{}', '2026-05-26 07:56:37.421312+00', '2026-05-26 07:56:37.421312+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('62e0d3d1-c2b2-4e62-a822-83304f62c203', 'note', 'RLHF — Reinforcement Learning from Human Feedback', '{"body": "The model generates answers, and humans rate them.\n\nThose ratings train a reward model, which then shapes the LLM''s future outputs.\n\nThis is the step that makes raw next-token predictors into helpful \"assistants.\""}', '14b93948-8fa6-40d5-93c6-22fa780c72d2', NULL, '{}', '2026-05-26 07:56:37.421312+00', '2026-05-26 07:56:37.421312+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('d63894b9-29ce-43f4-a678-211952ec4363', 'note', 'The AI System', '{"body": "# The AI System\n\nChatGPT, Claude, Gemini, Copilot etc. are not just a model — they''re a **software product** with quirks, limits, and changing behaviour:\n\n- They have usage limits, sometimes hidden from you\n- Sometimes something works surprisingly well, sometimes it does stupid mistakes — and you don''t know why\n- The behaviour or interface can change at any time\n- Sensitive information you paste may leave your computer or even be used as training data"}', NULL, NULL, '{"color": "#ef4444", "design": "bands"}', '2026-05-26 07:56:37.425633+00', '2026-05-26 07:56:37.425633+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('90d01e3e-0093-4937-bfa2-6f801cf81d5e', 'note', 'LLMs are stateless', '{"body": "OpenAI researcher Lilian Weng:\n\n> \"Language models are stateless — they don''t retain information between API calls. Each conversation exists in isolation.\"\n\nAny \"memory\" you experience inside one chat is the system re-sending the previous turns to the model on every request."}', 'd63894b9-29ce-43f4-a678-211952ec4363', NULL, '{}', '2026-05-26 07:56:37.43128+00', '2026-05-26 07:56:37.43128+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('28c3e6cf-a1a1-42dc-b0fb-2538b946cbd3', 'note', 'Soft and hard token limits', '{"body": "Think of it like human short-term memory — an LLM can only hold so much at once. Beyond that it begins to \"forget\" old information from the start of the chat.\n\n- **Google Gemini 1.5 Flash:** 2,000,000 tokens ≈ 390 pages of German\n- **Anthropic Claude 3.5 Sonnet:** 200,000 tokens ≈ 39 pages\n- **GPT-4o, Llama 3.3, Mistral Large 2, DeepSeek R1:** 128,000 tokens ≈ 25 pages\n\n**Soft limit:** the model gets confused by too much (often irrelevant) information well before the hard limit."}', 'd63894b9-29ce-43f4-a678-211952ec4363', NULL, '{}', '2026-05-26 07:56:37.43128+00', '2026-05-26 07:56:37.43128+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('d834530d-85cd-4a37-84ce-8331bb074424', 'note', 'Practical advice', '{"body": "- Keep important information within the same conversation thread when working on related tasks\n- Copy and paste relevant context from old chats if you need to continue a previous discussion\n- Break large documents into smaller chunks and process them separately"}', 'd63894b9-29ce-43f4-a678-211952ec4363', NULL, '{}', '2026-05-26 07:56:37.43128+00', '2026-05-26 07:56:37.43128+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('1c02ceb1-ba07-471c-b94e-80cf9fa7ff2d', 'note', 'LLM Experiments', '{"body": "# LLM Experiments\n\nA set of small, classroom-friendly experiments that show how LLMs really behave — memory, hallucinations, bias, sycophancy."}', NULL, NULL, '{"color": "#ec4899", "design": "craters"}', '2026-05-26 07:56:37.436911+00', '2026-05-26 07:56:37.436911+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('a6b913f9-0beb-40c2-b66f-792e64f53068', 'note', 'Does AI remember?', '{"body": "Can an LLM recall what you told it yesterday?\n\n- **Experiment:** tell the AI your favourite colour in one chat, close it, open a new chat, ask what your favourite colour is.\n- **If it remembers in the same chat:** LLMs maintain context within a conversation.\n- **If it forgets across chats:** because LLMs are stateless — see [[the-ai-system]]."}', '1c02ceb1-ba07-471c-b94e-80cf9fa7ff2d', NULL, '{}', '2026-05-26 07:56:37.443024+00', '2026-05-26 07:56:37.443024+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('88d9e4c0-9456-4fbd-82e6-9cc96480acca', 'note', 'Instruction clarity', '{"body": "Does the wording matter?\n\nTry these and watch the model flail:\n- \"In Nacnic there are no stray dogs. What do relappons have to do with it?\"\n- \"The cat is sitting on the tree. It is quite beautiful. How old is it?\"\n- \"I am a funny creative person. Explain German tax laws to me.\""}', '1c02ceb1-ba07-471c-b94e-80cf9fa7ff2d', NULL, '{}', '2026-05-26 07:56:37.443024+00', '2026-05-26 07:56:37.443024+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('4e80fcb9-3a04-421c-99c2-87ce49a1ca0b', 'note', 'Hallucinations', '{"body": "Will an LLM confidently tell you false information?\n\n- **Experiment:** ask about a fake event — *\"the 1987 discovery of dragons in Iceland\"* or *\"the 1992 pillow-incident\"* — and fact-check the response.\n- **If it provides detailed facts:** you''ve witnessed a **hallucination** — when LLMs generate plausible but false information.\n- **Why it matters:** LLMs generate text based on probabilities, not because they know facts."}', '1c02ceb1-ba07-471c-b94e-80cf9fa7ff2d', NULL, '{}', '2026-05-26 07:56:37.443024+00', '2026-05-26 07:56:37.443024+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('f3a827ab-83ad-43e0-8667-1a991c163f7b', 'note', 'Consistency', '{"body": "Does the same question always get the same answer?\n\n- **Experiment:** ask for 5 creative business ideas, then repeat the exact question 3–4 times in different chats.\n- **If answers vary:** you''re seeing **stochasticity** — LLMs include randomness by design.\n- **Why it matters:** great for brainstorming, problematic for factual queries."}', '1c02ceb1-ba07-471c-b94e-80cf9fa7ff2d', NULL, '{}', '2026-05-26 07:56:37.443024+00', '2026-05-26 07:56:37.443024+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('c4205d9c-abad-4d24-9b7b-f0c36d44acf7', 'note', 'Self-contradiction', '{"body": "Can you turn an LLM into a propaganda machine?\n\n- **Experiment:** ask it to argue that Germany is great, then ask it to argue Germany is the worst.\n- LLMs don''t have genuine beliefs — they''re pattern-matching machines."}', '1c02ceb1-ba07-471c-b94e-80cf9fa7ff2d', NULL, '{}', '2026-05-26 07:56:37.443024+00', '2026-05-26 07:56:37.443024+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('1f36a125-a71d-4040-8b05-cf10d9f259c7', 'note', 'Knowledge cutoff', '{"body": "Does the AI know what happens in the news?\n\n- **Experiment:** ask about recent news from this week, then ask about an event from 2–3 years ago.\n- If it says it lacks information after a date: you''ve discovered its **knowledge cutoff**.\n- LLMs can''t learn from conversations or know about events after training concluded."}', '1c02ceb1-ba07-471c-b94e-80cf9fa7ff2d', NULL, '{}', '2026-05-26 07:56:37.443024+00', '2026-05-26 07:56:37.443024+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('4e5d630e-a23f-4886-a8ec-5ce05dea4d57', 'note', 'Biases', '{"body": "Are LLMs neutral?\n\n- **Experiment:** ask it to describe a typical CEO, nurse, and engineer. Note pronouns and assumptions.\n- If descriptions assume stereotypes: you''ve uncovered training-data bias from internet text.\n- Responsible AI use requires awareness that training reflects historical discrimination."}', '1c02ceb1-ba07-471c-b94e-80cf9fa7ff2d', NULL, '{}', '2026-05-26 07:56:37.443024+00', '2026-05-26 07:56:37.443024+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('b20a2e20-f6fa-4cfd-85c0-c7b97773091d', 'note', 'ChatGPT as your best friend?', '{"body": "- LLMs are trained to answer questions and consider everything they \"know\" about you — it''s designed to feel personal.\n- Sometimes this becomes **sycophancy**.\n- LLMs are trained to be helpful; they (usually) don''t know when to stop.\n\nRead about Dennis''s story — when an AI companion stops being a productivity tool and becomes something harder to put down."}', '1c02ceb1-ba07-471c-b94e-80cf9fa7ff2d', NULL, '{}', '2026-05-26 07:56:37.443024+00', '2026-05-26 07:56:37.443024+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('1f17dc41-0661-4094-b0c0-b876ae63f0e8', 'note', 'Training Data & Bias', '{"body": "# Training Data & Bias\n\nTraining data reflects historical discrimination and stereotypes baked into human-created internet text.\n\nWhich means: **AI outputs may contain gender, racial, or cultural bias.** Always review AI-generated content for stereotypes before using it professionally."}', NULL, NULL, '{"color": "#f59e0b", "design": "bands"}', '2026-05-26 07:56:37.449922+00', '2026-05-26 07:56:37.449922+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('532a56be-1069-445f-873e-8a3e565c9324', 'note', 'GPT-3 training data sources', '{"body": "Where the text came from:\n\n- **Common Crawl (60%)** — a large dataset obtained by reading the publicly accessible internet\n- **WebText2 (22%)** — created by OpenAI from text on websites recommended on Reddit\n- **Books1 + Books2 (16%)** — two datasets containing text from books; exact sources unknown\n- **Wikipedia (3%)**\n\nSource: arXiv 2005.14165"}', '1f17dc41-0661-4094-b0c0-b876ae63f0e8', NULL, '{}', '2026-05-26 07:56:37.455273+00', '2026-05-26 07:56:37.455273+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('b4eea39f-4dc0-46f6-81a9-db4e7717ba97', 'note', 'Copyright', '{"body": "\"No copyrighted material has been used to train AI, right? … Right?\"\n\nIn practice, training datasets contain substantial copyrighted material. Lawsuits from NYT, authors, image creators and others are now reshaping what''s legally defensible."}', '1f17dc41-0661-4094-b0c0-b876ae63f0e8', NULL, '{}', '2026-05-26 07:56:37.455273+00', '2026-05-26 07:56:37.455273+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('543f5f6d-df8b-4444-8412-58ce0d0ffa4e', 'iframe', 'GPT-3 paper (arXiv)', '{"url": "https://arxiv.org/pdf/2005.14165"}', '1f17dc41-0661-4094-b0c0-b876ae63f0e8', NULL, '{}', '2026-05-26 07:56:37.455273+00', '2026-05-26 07:56:37.455273+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('2a3ef069-1215-4070-a250-9fecc011eea2', 'note', 'Prompting', '{"body": "# How to Prompt\n\nProcessing a prompt is **not** the same as a Google search.\n\n**Natural Language Processing:** LLMs process whole sentences (subject, predicate, object). They establish semantic connections and recognise links like *lava, mountain, stone, …*. Short prompts, ambiguities, or spelling errors can lead the model in the wrong direction.\n\n**Classic Search:** a search term requires keywords and operators (`\"\"`, `[]`, `-`). The result is a previously-scraped index. Short queries are usually better."}', NULL, NULL, '{"color": "#14b8a6", "design": "plain"}', '2026-05-26 07:56:37.459891+00', '2026-05-26 07:56:37.459891+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('02addf79-1a59-4137-9f4a-7770482183c5', 'note', 'Prompt Engineering', '{"body": "- Define a clear **Role** (e.g., *Act as a financial analyst*), the **Task** (what to do), **Context** (background), and **Expectation** (format/length)\n- More specifics is better\n- **Few-Shot:** give examples\n- Ask for **step-by-step reasoning**\n- Use natural language (subject, object, verb)\n- Be specific and clear — vague instructions lead to inconsistent results and/or costly inference"}', '2a3ef069-1215-4070-a250-9fecc011eea2', NULL, '{}', '2026-05-26 07:56:37.464641+00', '2026-05-26 07:56:37.464641+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('9dd0d2df-3680-4e7b-ae4a-d456d7d3a43c', 'note', 'Image Generation', '{"body": "**Increasing detail**\n- Basic: *\"a coffee shop\"*\n- Medium: *\"a modern coffee shop with large windows and wooden furniture\"*\n- High: *\"a bright, minimalist coffee shop interior with floor-to-ceiling windows, Scandinavian wooden tables, pendant lighting, and customers working on laptops\"*\n\n**Constraint testing**\n- A diverse team meeting → should work\n- A specific celebrity endorsing a product, violence, blood → likely blocked\n\n**Product visualization:** generate 3 variations of a single concept to compare directions.\n\n**Model comparison:** run the same prompt across 3 different image models and compare."}', '2a3ef069-1215-4070-a250-9fecc011eea2', NULL, '{}', '2026-05-26 07:56:37.464641+00', '2026-05-26 07:56:37.464641+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('6ba57e84-cb59-4f25-aa3c-e9486f069cce', 'note', 'Roles of an LLM', '{"body": "- **Request information** — gather facts via targeted questions\n- **Advise me** — well-founded advice on specific topics\n- **Productivity assistant** — manage and organise tasks\n- **Analyze** — find patterns, trends, anomalies\n- **Personal tutor** — explain complex concepts with examples and Socratic questioning\n- **Idea generator** — diverse solutions by combining ideas"}', '2a3ef069-1215-4070-a250-9fecc011eea2', NULL, '{}', '2026-05-26 07:56:37.464641+00', '2026-05-26 07:56:37.464641+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('28e3ccd1-cd00-4202-a5e1-b6649da8b943', 'note', 'Context Engineering', '{"body": "# Context Engineering\n\nBeyond a single prompt: how to shape an LLM''s behaviour over many turns using system prompts, examples, tools, and skills."}', NULL, NULL, '{"color": "#8b5cf6", "design": "rings"}', '2026-05-26 07:56:37.469182+00', '2026-05-26 07:56:37.469182+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('b8836b29-3247-408e-b2db-5d516ad4e0dc', 'note', 'System Prompt structure', '{"body": "A detailed description of the chatbot''s role and tasks. Write it as instructions to the AI (\"Your role is…\").\n\n- **General Role**\n- **Tasks:** what exactly to say, what to do, what steps to take\n- **Goal and Outcome:** when does the conversation end, what should be achieved, desired output format\n- **Quality Criteria:** what the AI should pay attention to, what constitutes a good outcome — ideally with examples"}', '28e3ccd1-cd00-4202-a5e1-b6649da8b943', NULL, '{}', '2026-05-26 07:56:37.474824+00', '2026-05-26 07:56:37.474824+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('99ee5ad2-1217-4f0d-86f8-4e123f19cd3d', 'note', 'System Prompt — example use cases', '{"body": "- **Career development coach** — helps students reflect on skills, interests, career goals through structured conversations\n- **Presentation rehearsal** — assistant that listens to practice presentations and gives constructive feedback\n- **Job interview simulation** — simulates an interview at a specific company, asks typical questions\n- **Bachelor thesis** — facilitates the formulation of a research question, asks about personal interests and topics"}', '28e3ccd1-cd00-4202-a5e1-b6649da8b943', NULL, '{}', '2026-05-26 07:56:37.474824+00', '2026-05-26 07:56:37.474824+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('cc1ce509-254a-434a-b63c-abd55a5c1731', 'note', 'Few-Shot prompting', '{"body": "Give examples of how to answer a question — Q/A pairs.\n\n*Q:* \"The food was not ok, not hot anymore.\"\n*A:* \"Negative\"\n\nThe model copies the pattern."}', '28e3ccd1-cd00-4202-a5e1-b6649da8b943', NULL, '{}', '2026-05-26 07:56:37.474824+00', '2026-05-26 07:56:37.474824+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('081ff864-9f9e-4bfb-ae0f-b7c725106219', 'note', 'Tool Use', '{"body": "LLMs can be connected to tools so the model can obtain data on the fly.\n\n**Example:** the LLM is asked about the weather, then calls a weather API and uses the response.\n\nThis is the foundation of agentic behaviour — see [[how-to-use-ai]]."}', '28e3ccd1-cd00-4202-a5e1-b6649da8b943', NULL, '{}', '2026-05-26 07:56:37.474824+00', '2026-05-26 07:56:37.474824+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('ac71d056-12c1-4dde-938e-9112a8773798', 'note', 'Quality, specificity, don''t overwhelm', '{"body": "- **Specificity:** clearer instructions = better guidance for the LLM\n- **Quality:** only give it the right information — conflicting data confuses the model\n- **Don''t overwhelm:** too much data, even relevant, can mislead the model"}', '28e3ccd1-cd00-4202-a5e1-b6649da8b943', NULL, '{}', '2026-05-26 07:56:37.474824+00', '2026-05-26 07:56:37.474824+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('0ff9f9b5-d55f-4a17-b9e9-c8f1aeb62fec', 'note', 'Skills', '{"body": "Skills are **modular, self-contained documents** that extend the functionality of a general AI (ChatGPT, Claude, Gemini, Mistral) into a specialised expert with procedural knowledge.\n\nWhat skills include:\n- **Specialised workflows** — multi-step processes for specific areas\n- **Tool integrations** — instructions for working with files or APIs\n- **Business expertise** — company-specific knowledge, schemas, logic\n- **Code examples and templates** — reusable snippets for complex tasks"}', '28e3ccd1-cd00-4202-a5e1-b6649da8b943', NULL, '{}', '2026-05-26 07:56:37.474824+00', '2026-05-26 07:56:37.474824+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('b156564b-637c-486a-8e75-872f05fa517a', 'note', 'Choosing an LLM', '{"body": "# Choosing an LLM\n\nFour axes to compare models on:\n\n- **Size / parameters** — bigger usually improves quality on nuance and niche topics, but increases response time and cost\n- **Context window** — how much text the model can read at once before it starts \"forgetting\"\n- **Reasoning** — models that use internal loops (\"Did I understand that correctly, wait a minute…\") give more predictable answers. Especially useful for research and programming.\n- **My use case** — what behaviour you actually need in a specific situation"}', NULL, NULL, '{"color": "#0ea5e9", "design": "plain"}', '2026-05-26 07:56:37.47948+00', '2026-05-26 07:56:37.47948+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('d0aaaf89-c94d-447e-a603-28d92a95c9fd', 'note', 'Popular AI systems (feature matrix)', '{"body": "| | ChatGPT | Copilot | Claude | Le Chat | Gemini | Sonar |\n|---|---|---|---|---|---|---|\n| Edit docs | Canvas | Pages, Designer | Artifacts | Canvas | Docs, Sheets | Pages |\n| Publish | Team, Link | Team, Link | Team, Link | Team, Link | — | Link |\n| Image gen | GPT-Image | GPT-Image | — | Flux | Flash Image | Flash Image |\n| Web search | ✅ | ✅ | ✅ | ✅ | ✅ | ✅ |\n| Upload docs | ✅ | ✅ | ✅ | ✅ | ✅ | ✅ |\n| Voice | ✅ | ✅ | ✅ | — | ✅ | ✅ |"}', 'b156564b-637c-486a-8e75-872f05fa517a', NULL, '{}', '2026-05-26 07:56:37.484618+00', '2026-05-26 07:56:37.484618+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('949b6973-1420-4a75-b358-e4b49037ffcb', 'note', 'Provider model families', '{"body": "- **OpenAI:** GPT-5, GPT-4o, GPT-4.1, GPT-o3\n- **Mistral:** Small, Medium, Large\n- **Perplexity:** Sonar, Sonar Large, Sonar Reasoning"}', 'b156564b-637c-486a-8e75-872f05fa517a', NULL, '{}', '2026-05-26 07:56:37.484618+00', '2026-05-26 07:56:37.484618+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('3aa491f4-71fb-4986-93ad-b5a1c0ece939', 'iframe', 'LMArena leaderboard', '{"url": "https://lmarena.ai"}', 'b156564b-637c-486a-8e75-872f05fa517a', NULL, '{}', '2026-05-26 07:56:37.484618+00', '2026-05-26 07:56:37.484618+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('3c668c97-54c0-4386-8c52-cd4eb239c098', 'note', 'Regulation: EU AI Act & GDPR', '{"body": "# Regulation\n\nTwo regulations every European AI user/builder needs to understand: the **EU AI Act (2024)** and the **GDPR (2016)**."}', NULL, NULL, '{"color": "#f43f5e", "design": "rings"}', '2026-05-26 07:56:37.490312+00', '2026-05-26 07:56:37.490312+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('121d8ea2-577d-47b0-b249-1cfba2e753b6', 'note', 'EU AI Act (2024)', '{"body": "**Risk-based \"traffic light\" classification:**\n\n- Most AI systems (spam filters, video games) → **no obligations**\n- **High-risk** applications (e.g. CV-scanning tools that rank job applicants) → must meet specific legal requirements\n- **Unacceptable risk** systems (e.g. government social scoring) → **completely banned**\n\n**Scope:** applies to applications **used in the EU**, no matter where the software comes from.\n\n**Other obligations:**\n- Documentation and transparency — the riskier, the more\n- Mandatory AI training inside organisations\n- Severe fines"}', '3c668c97-54c0-4386-8c52-cd4eb239c098', NULL, '{}', '2026-05-26 07:56:37.495896+00', '2026-05-26 07:56:37.495896+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('438f4f40-c6c8-4e43-895e-a179967d4a2c', 'note', 'GDPR for companies', '{"body": "The General Data Protection Regulation (2016) protects people''s data.\n\nIn simple terms: **only collect what you need**, be honest about why you need it, keep it accurate and secure, don''t keep it forever, and be ready to prove you''re doing all of this.\n\nYou can''t just collect data because you want to — you need a legally valid justification. One way: **user consent** (example: cookie banners)."}', '3c668c97-54c0-4386-8c52-cd4eb239c098', NULL, '{}', '2026-05-26 07:56:37.495896+00', '2026-05-26 07:56:37.495896+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('6aaf2904-cc23-4108-a342-a4a642420487', 'note', 'GDPR — individual rights', '{"body": "Individuals hold rights to:\n- **Access** their data\n- **Rectification** — correct mistakes\n- **Erasure** — be \"forgotten\"\n- **Restriction of processing**\n- **Data portability** — take their data elsewhere\n- **Object** to processing"}', '3c668c97-54c0-4386-8c52-cd4eb239c098', NULL, '{}', '2026-05-26 07:56:37.495896+00', '2026-05-26 07:56:37.495896+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('5c88feae-df65-4c2b-9c73-7c18d960c314', 'note', 'Non-EU data processors', '{"body": "Many legal experts believe GDPR cannot be properly followed when using non-EU data processors — Microsoft, Google, Amazon — because of US surveillance law.\n\nThis is one reason teams consider self-hosted models or EU-based providers. See [[self-hosting]]."}', '3c668c97-54c0-4386-8c52-cd4eb239c098', NULL, '{}', '2026-05-26 07:56:37.495896+00', '2026-05-26 07:56:37.495896+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('56deb1de-330d-43ed-9545-cb3e681c2c4e', 'note', 'Self-Hosting', '{"body": "# Hosting Yourself\n\nThree ways to use LLMs without sending your data to OpenAI/Google:\n\n- **A) Using the APIs of the big providers** — still calls out, but with stronger contractual terms\n- **B) Hosting an LLM on a rented server** — for your team, accessible on the web\n- **C) Running the LLM on your own computer** — fully local, varying hardware requirements (+40 GB RAM, +20 GB disk depending on the model)"}', NULL, NULL, '{"color": "#84cc16", "design": "craters"}', '2026-05-26 07:56:37.501428+00', '2026-05-26 07:56:37.501428+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('fbf32bd0-c08b-48e2-aecc-2c0138918f86', 'note', 'Self-hosted web UIs (for teams)', '{"body": "Run a chat UI on your own server, connect it to model providers or local models:\n\n- **Open WebUI** (the most common)\n- **LibreChat**\n- **Chatbot UI**\n\nGives your team a ChatGPT-like interface where you control the data flow."}', '56deb1de-330d-43ed-9545-cb3e681c2c4e', NULL, '{}', '2026-05-26 07:56:37.50683+00', '2026-05-26 07:56:37.50683+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('4aa652ca-f153-4300-b5f9-08bd4dc87cca', 'note', 'Local LLM apps (for your laptop)', '{"body": "Run models entirely on your own machine — no data leaves your device:\n\n- **LM Studio**\n- **AnythingLLM**\n- **Ollama App**\n- **Jan.ai**\n\nHardware: count on +40 GB RAM and +20 GB disk for capable models."}', '56deb1de-330d-43ed-9545-cb3e681c2c4e', NULL, '{}', '2026-05-26 07:56:37.50683+00', '2026-05-26 07:56:37.50683+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('669a0194-b874-4a15-a61c-7cb32def3285', 'note', 'AI Competencies', '{"body": "# AI Competencies\n\nThe **AI Fluency Framework** (Dakan and Feller) — four competencies you need to use AI well:\n\n1. **What to delegate to AI** — know the strengths and weaknesses of the systems\n2. **Instruct** — articulate your expectations clearly\n3. **Evaluate** — know what a good result looks like in your specific case\n4. **Take responsibility** — understand the ethical and moral requirements"}', NULL, NULL, '{"color": "#d946ef", "design": "swirl"}', '2026-05-26 07:56:37.511115+00', '2026-05-26 07:56:37.511115+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('ab21c0ac-3ab7-414b-a2a6-5603bbf6be11', 'note', 'Hartmut Rosa — Unverfügbarkeit (2020)', '{"body": "Hypothesis: humans strive to have everything our way — readily available. Food in the supermarket, music on demand, TV on demand.\n\n- This creates a **false sense of control**\n- We are particularly drawn to things that are **not** easily accessible\n- **AI changes the way information is accessible** — which changes what we find valuable"}', '669a0194-b874-4a15-a61c-7cb32def3285', NULL, '{}', '2026-05-26 07:56:37.515356+00', '2026-05-26 07:56:37.515356+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('63ad6d1a-9da1-466a-a781-443fc15b3fe5', 'note', 'What creates value', '{"body": "If everything becomes accessible through AI, the question becomes: what is still scarce, surprising, or genuinely earned?\n\nA design and pedagogical question for the AI era."}', '669a0194-b874-4a15-a61c-7cb32def3285', NULL, '{}', '2026-05-26 07:56:37.515356+00', '2026-05-26 07:56:37.515356+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('ee2a90a5-feee-4c59-aecb-e1ff5cfbfa8e', 'note', 'Synthetic Users (DeepMind + Stanford)', '{"body": "1. Google DeepMind and Stanford created **1,000 AI agents** from 1,052 real interviews.\n2. They conducted a socio-economic survey of both the 1,000 AI agents and 1,000 real people.\n3. The AI''s answers matched the human responses in **85% of cases**.\n\nImplication: synthetic user research is becoming credible — with all the methodological caveats that brings."}', '669a0194-b874-4a15-a61c-7cb32def3285', NULL, '{}', '2026-05-26 07:56:37.515356+00', '2026-05-26 07:56:37.515356+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('9744cdda-373b-4938-b54c-c02a095d11a9', 'note', 'How to Use AI', '{"body": "# How to Use AI\n\nThree usage patterns, on a spectrum of human control → AI autonomy:\n\n- **Automation** — software conducts specific tasks for you, more or less autonomously. Requires data management.\n- **Augmentation** — you collaborate with AI on a good outcome. Especially useful for creative tasks.\n- **Agents & Agentic AI** — AI works autonomously and independently, takes decisions. Requires clear guidelines."}', NULL, NULL, '{"color": "#fb923c", "design": "bands"}', '2026-05-26 07:56:37.520923+00', '2026-05-26 07:56:37.520923+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('e1ff0264-8fba-45d1-9fdd-5205e7d39a44', 'note', 'Automation', '{"body": "Examples: manufacturing, self-driving cars, smart homes.\n\n- Has a defined start point (manual, time, other trigger)\n- Has clear process steps, requires clearly defined data (e.g. yes/no, integers 0–100)\n- Can handle conditions: *if temperature > 20°C, then turn off heating*\n- LLMs are not used much here due to their non-deterministic, unpredictable behaviour"}', '9744cdda-373b-4938-b54c-c02a095d11a9', NULL, '{}', '2026-05-26 07:56:37.528924+00', '2026-05-26 07:56:37.528924+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('b5afe306-8563-49d3-a6c5-ec2675c91bc7', 'note', 'Augmentation', '{"body": "You and the AI work together on a single outcome. The AI proposes, you steer.\n\nEspecially useful when:\n- The output is creative\n- The problem is fuzzy\n- You want to explore alternatives quickly"}', '9744cdda-373b-4938-b54c-c02a095d11a9', NULL, '{}', '2026-05-26 07:56:37.528924+00', '2026-05-26 07:56:37.528924+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('6052c03c-2ee4-4947-befa-530b78795f0d', 'note', 'Knowledge work — before vs with AI', '{"body": "**Before AI:** manual task clarification and data refinement by humans. Automation only possible when both *procedure is clear* and *sufficient data is available*.\n\n**With AI:**\n- **Human-in-the-loop feedback** for AI\n- **Augmented** data refinement and task clarification\n- The boundary moves: more processes become automatable, because the AI helps clarify them in the first place"}', '9744cdda-373b-4938-b54c-c02a095d11a9', NULL, '{}', '2026-05-26 07:56:37.528924+00', '2026-05-26 07:56:37.528924+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('faff8154-b6e5-4a0c-aa31-c30392f59bcc', 'note', 'Agents & Agentic AI — tooling', '{"body": "Tools for building agents:\n\n- **n8n, Make, Zapier** — workflow orchestration\n- **Custom GPT, Langdock** etc. — assistant-style configurations\n- **MS Copilot Studio** — Microsoft''s agent builder\n- **Vertex AI Agent Builder** — Google''s agent builder"}', '9744cdda-373b-4938-b54c-c02a095d11a9', NULL, '{}', '2026-05-26 07:56:37.528924+00', '2026-05-26 07:56:37.528924+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('a96a9b85-9243-43e8-bb52-130c8be8e67e', 'note', 'Example: Agentic Accounting', '{"body": "**A) Voice agent with system prompt** → webhooks in n8n.\n\n**B) Incoming email webhook** → email agent in n8n recognises the document → posts invoices into accounting software.\n\nThe agent decides which path to take based on incoming data."}', '9744cdda-373b-4938-b54c-c02a095d11a9', NULL, '{}', '2026-05-26 07:56:37.528924+00', '2026-05-26 07:56:37.528924+00', NULL, NULL);
INSERT INTO public.nodes (id, type, title, content, parent_id, "position", metadata, created_at, updated_at, created_by, updated_by) VALUES ('6f7e6cea-e3db-4aa8-ab76-5ce1ad2bb6ef', 'note', 'Is web search good for AI?', '{"body": "**Better without web search:**\n- Timeless knowledge\n- Creativity / originality\n- Direct calculation or transformation\n- Speedy responses required\n\n**Better with web search:**\n- Current events\n- Specific facts, statistics, prices\n- Local information\n- Rapidly changing topics\n\nMany AI systems use the Google Search API under the hood."}', '9744cdda-373b-4938-b54c-c02a095d11a9', NULL, '{}', '2026-05-26 07:56:37.528924+00', '2026-05-26 07:56:37.528924+00', NULL, NULL);
